use std::sync::Arc;

use oxide_ml_core::DType;
use oxide_ml_graph::{CanonicalGraph, GraphHash};

use crate::plan_hash::{CanonicalPlan, MEMORY_PLAN_VERSION, PlanHash};

/// Process-local identity of a CUDA context.
///
/// The value is generated by a monotonic counter and is never reused inside a
/// process. It is not a driver pointer and must not be persisted.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ArenaContextId(pub u64);

/// Stable identity of a physical device inside one process.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct DeviceId {
    pub ordinal: u32,
    pub uuid: Option<[u8; 16]>,
    pub name: String,
    pub compute_capability: (u16, u16),
    pub total_memory: u64,
}

impl DeviceId {
    pub fn new(
        ordinal: u32,
        uuid: Option<[u8; 16]>,
        name: impl Into<String>,
        compute_capability: (u16, u16),
        total_memory: u64,
    ) -> Self {
        DeviceId {
            ordinal,
            uuid,
            name: name.into(),
            compute_capability,
            total_memory,
        }
    }
}

/// Complete identity of a persistent arena lookup.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ArenaKey {
    pub graph_hash: GraphHash,
    pub plan_hash: PlanHash,
    pub device_id: DeviceId,
    pub context_id: ArenaContextId,
    pub dtype: DType,
    pub memory_plan_version: u32,
}

impl ArenaKey {
    pub fn new(
        graph_hash: GraphHash,
        plan_hash: PlanHash,
        device_id: DeviceId,
        context_id: ArenaContextId,
        dtype: DType,
        memory_plan_version: u32,
    ) -> Self {
        ArenaKey {
            graph_hash,
            plan_hash,
            device_id,
            context_id,
            dtype,
            memory_plan_version,
        }
    }

    pub fn from_descriptor(descriptor: &ArenaDescriptor) -> Self {
        ArenaKey {
            graph_hash: descriptor.graph.hash(),
            plan_hash: descriptor.plan.hash(),
            device_id: descriptor.device_id.clone(),
            context_id: descriptor.context_id,
            dtype: descriptor.dtype,
            memory_plan_version: descriptor.memory_plan_version,
        }
    }
}

/// Exact descriptor stored next to an arena.
///
/// Hash equality alone never reuses an arena: the registry also compares this
/// descriptor. `backend_layout` is an opaque, deterministic encoding supplied
/// by the backend (for CUDA it includes the actual slot/assignment layout and
/// raw ValueId bindings that the persistent arena needs to execute).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArenaDescriptor {
    pub graph: Arc<CanonicalGraph>,
    pub plan: Arc<CanonicalPlan>,
    pub device_id: DeviceId,
    pub context_id: ArenaContextId,
    pub dtype: DType,
    pub memory_plan_version: u32,
    pub backend_layout: Vec<u8>,
}

impl ArenaDescriptor {
    pub fn new(
        graph: CanonicalGraph,
        plan: CanonicalPlan,
        device_id: DeviceId,
        context_id: ArenaContextId,
        dtype: DType,
    ) -> Self {
        ArenaDescriptor {
            graph: Arc::new(graph),
            plan: Arc::new(plan),
            device_id,
            context_id,
            dtype,
            memory_plan_version: MEMORY_PLAN_VERSION,
            backend_layout: Vec::new(),
        }
    }

    pub fn with_backend_layout(mut self, layout: Vec<u8>) -> Self {
        self.backend_layout = layout;
        self
    }

    pub fn graph_hash(&self) -> GraphHash {
        self.graph.hash()
    }

    pub fn plan_hash(&self) -> PlanHash {
        self.plan.hash()
    }
}
